def transform(grid):
 h,w=len(grid),len(grid[0]);out=[r[:] for r in grid]
 ones=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==1]
 six=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==6]
 lines=set()
 for a in range(len(ones)):
  for b in range(a+1,len(ones)):
   r,c=ones[a];R,C=ones[b]
   if abs(R-r)==abs(C-c):
    dr=1 if R>r else -1;dc=1 if C>c else -1
    for k in range(abs(R-r)+1):out[r+k*dr][c+k*dc]=1
    lines.add(r-c) if dr==dc else lines.add(r+c)
 for r,c in six:
  if r-c in lines or r+c in lines:
   dr,dc=(1,-1) if r-c in lines else (1,1)
   rr,cc=r,c
   while 0<=rr-dr<h and 0<=cc-dc<w:rr-=dr;cc-=dc
   while 0<=rr<h and 0<=cc<w:out[rr][cc]=6;rr+=dr;cc+=dc
 return out
